"""Generate HTML, EPUB, and PDF for both Moon Base books."""

import os, re, io, zipfile, html as html_mod, textwrap
from xml.sax.saxutils import escape as xml_escape
from datetime import datetime
from weasyprint import HTML

BASE = os.path.expanduser("~/books/Moon_Base_One")

BOOKS = {
    "Moon_Base_The_Beginning": {
        "dir": "Moon_Base_The_Beginning",
        "title": "Moon Base - The Beginning",
        "subtitle": "A Lunar Settlement Chronicle \u2014 Book 1",
        "author": "Robert Mills",
        "series": "A Lunar Settlement Chronicle"
    },
    "Moon_Base_Homecoming": {
        "dir": "Moon_Base_Homecoming",
        "title": "Moon Base - Homecoming",
        "subtitle": "A Lunar Settlement Chronicle \u2014 Book 2",
        "author": "Robert Mills",
        "series": "A Lunar Settlement Chronicle"
    }
}

def load_manuscript(book_dir):
    """Load manuscript and extract chapters."""
    path = os.path.join(BASE, book_dir, "manuscript.md")
    with open(path, "r", encoding="utf-8") as f:
        content = f.read()

    # Split into chapters by ## headers
    lines = content.split("\n")
    chapters = []
    current_title = None
    current_lines = []
    front_matter = []
    in_front_matter = True

    for line in lines:
        stripped = line.strip()
        # Check for chapter start
        if re.match(r'^## (Chapter|CHAPTER|Part|PART)\s+\d+', stripped) or \
           re.match(r'^## Chapter \d+', stripped):
            in_front_matter = False
            if current_title is not None:
                chapters.append((current_title, "\n".join(current_lines).strip()))
            current_title = stripped.lstrip("# ").strip()
            current_lines = [line]
        elif re.match(r'^## \d+ —', stripped) and not in_front_matter:
            # Some chapters have "## 1 — Title" format
            if current_title is not None:
                chapters.append((current_title, "\n".join(current_lines).strip()))
            current_title = stripped.lstrip("# ").strip()
            current_lines = [line]
        elif re.match(r'^## Table of Contents', stripped) and in_front_matter:
            current_lines.append(line)
        elif in_front_matter:
            current_lines.append(line)
        else:
            current_lines.append(line)

    # Don't forget last chapter
    if current_title is not None and not in_front_matter:
        chapters.append((current_title, "\n".join(current_lines).strip()))

    return chapters

def markdown_to_html(text):
    """Convert markdown to HTML with chapter formatting."""
    lines = text.split("\n")
    html_parts = []
    in_list = False

    for line in lines:
        stripped = line.strip()

        # Skip chapter headers (already handled)
        if re.match(r'^## (Chapter|CHAPTER|Part|PART)', stripped):
            continue
        if re.match(r'^## \d+ —', stripped):
            continue
        if stripped.startswith("# ") or stripped.startswith("## "):
            continue

        # Horizontal rule
        if stripped == "---":
            if in_list:
                html_parts.append("</ul>")
                in_list = False
            html_parts.append("<hr />")
            continue

        # Empty line
        if not stripped:
            if in_list:
                html_parts.append("</ul>")
                in_list = False
            html_parts.append("")
            continue

        # List items
        if stripped.startswith("- ") or stripped.startswith("* "):
            if not in_list:
                html_parts.append("<ul>")
                in_list = True
            html_parts.append(f"<li>{xml_escape(stripped[2:])}</li>")
            continue

        if stripped.startswith("1. ") or stripped.startswith("2. "):
            if not in_list:
                html_parts.append("<ol>")
                in_list = True
            html_parts.append(f"<li>{xml_escape(stripped[3:])}</li>")
            continue

        # End list if we hit a non-list item
        if in_list:
            html_parts.append("</ul>")
            in_list = False

        # Check for mission AI / character quotes (italic content at start)
        if stripped.startswith("*Mission AI:") or stripped.startswith("*Mission AI "):
            capture = []
            capture.append(stripped)
            html_parts.append(f'<p class="mission-ai">{xml_escape(stripped)}</p>')
            continue

        # Italic lines (transitions, quotes)
        if stripped.startswith("*") and stripped.endswith("*") and len(stripped) > 3:
            html_parts.append(f'<p class="transition-note">{xml_escape(stripped.strip("*"))}</p>')
            continue

        # Check for italic line with quote
        if stripped.startswith("*") and len(stripped) > 10:
            html_parts.append(f'<p class="character-quote">{xml_escape(stripped)}</p>')
            continue

        # Regular paragraph - detect first paragraph after chapter title
        html_parts.append(f"<p>{xml_escape(stripped)}</p>")

    if in_list:
        html_parts.append("</ul>")

    return "\n".join(html_parts)

