def create_epub(html_content, output_path, title, author):
    """Generate EPUB3 from HTML content using pure Python."""
    import re as _re

    # Split HTML into chapters by looking for <h2>Chapter X</h2>
    chapter_pattern = _re.compile(r'<h2>Chapter \d+</h2>\s*<h2>(.*?)</h2>(.*?)(?=<div class="chapter-body|<div class="back-cover|$)', _re.DOTALL)

    matches = list(chapter_pattern.finditer(html_content))
    chapters = []
    for m in matches:
        ch_title = m.group(1)
        ch_body = m.group(2)
        chapters.append((ch_title, ch_body))

    if not chapters:
        # Fallback: whole HTML as one chapter
        chapters = [(title, html_content)]

    book_id = f"urn:uuid:{abs(hash(title + author)) & 0xFFFFFFFFFFFFFFFF:016x}"
    book_id_t = f"urn:uuid:{abs(hash(title + author + 't')) & 0xFFFFFFFFFFFFFFFF:016x}"

    buf = io.BytesIO()
    zf = zipfile.ZipFile(buf, 'w', zipfile.ZIP_DEFLATED)

    # 1. mimetype (must be first, uncompressed)
    info = zipfile.ZipInfo('mimetype')
    info.compress_type = zipfile.ZIP_STORED
    zf.writestr(info, 'application/epub+zip')

    # 2. META-INF/container.xml
    zf.writestr('META-INF/container.xml',
        '<?xml version="1.0" encoding="UTF-8"?>\n'
        '<container version="1.0" xmlns="urn:oasis:names:tc:opendocument:xmlns:container">\n'
        '  <rootfiles>\n'
        '    <rootfile full-path="OEBPS/content.opf" media-type="application/oebps-package+xml"/>\n'
        '  </rootfiles>\n'
        '</container>')

    # 3. Extract CSS from HTML
    css_match = _re.search(r'<style>(.*?)</style>', html_content, _re.DOTALL)
    css = css_match.group(1) if css_match else ''
    zf.writestr('OEBPS/css/style.css', css)

    manifest = []
    spine = []

    def add_item(id_, href, mtype, props=None):
        p = f' properties="{props}"' if props else ''
        manifest.append(f'<item id="{id_}" href="xhtml/{href}" media-type="{mtype}"{p}/>')
        spine.append(f'<itemref idref="{id_}"/>')

    # Extract body content for cover/toc
    body_match = _re.search(r'<body>(.*?)</body>', html_content, _re.DOTALL)
    body_content = body_match.group(1) if body_match else ''

    # Extract cover page
    cover_match = _re.search(r'<div class="cover-page">(.*?)</div>', body_content, _re.DOTALL)
    cover_text = cover_match.group(1) if cover_match else f'<h1>{xml_escape(title)}</h1>'

    # Cover XHTML
    cover_xhtml = f'''<?xml version="1.0" encoding="UTF-8"?>
<html xmlns="http://www.w3.org/1999/xhtml">
<head><title>Cover</title>
<link rel="stylesheet" type="text/css" href="css/style.css"/></head>
<body><div class="cover-page">{cover_text}</div></body></html>'''
    zf.writestr('OEBPS/xhtml/cover.xhtml', cover_xhtml)
    add_item('cover', 'cover.xhtml', 'application/xhtml+xml')

    # Extract copyright page
    copyright_match = _re.search(r'<div class="copyright-page">(.*?)</div>', body_content, _re.DOTALL)
    if copyright_match:
        copyright_xhtml = f'''<?xml version="1.0" encoding="UTF-8"?>
<html xmlns="http://www.w3.org/1999/xhtml">
<head><title>Copyright</title>
<link rel="stylesheet" type="text/css" href="css/style.css"/></head>
<body><div class="copyright-page">{copyright_match.group(1)}</div></body></html>'''
        zf.writestr('OEBPS/xhtml/copyright.xhtml', copyright_xhtml)
        add_item('copyright', 'copyright.xhtml', 'application/xhtml+xml')

    # TOC page
    toc_match = _re.search(r'<div class="toc-page">(.*?)</div>', body_content, _re.DOTALL)
    if toc_match:
        toc_xhtml = f'''<?xml version="1.0" encoding="UTF-8"?>
<html xmlns="http://www.w3.org/1999/xhtml">
<head><title>Table of Contents</title>
<link rel="stylesheet" type="text/css" href="css/style.css"/></head>
<body><div class="toc-page">{toc_match.group(1)}</div></body></html>'''
        zf.writestr('OEBPS/xhtml/toc.xhtml', toc_xhtml)
        add_item('toc', 'toc.xhtml', 'application/xhtml+xml')

    # Chapter XHTML
    nav_items = []
    chapter_count = 0
    for idx, (ch_title, ch_body) in enumerate(chapters):
        chapter_count += 1
        slug = _re.sub(r'[^\w]', '-', ch_title.lower())[:40] or f'ch-{idx+1:02d}'
        fn = f'chapter_{idx+1:02d}_{slug}.xhtml'

        # Get full chapter HTML from body
        ch_pattern = _re.compile(
            rf'<h2>Chapter {idx+1}</h2>\s*<h2>{_re.escape(ch_title)}</h2>(.*?)(?=<h2>Chapter {idx+2}|<div class="back-cover|$)',
            _re.DOTALL
        )
        ch_section_match = ch_pattern.search(body_content)
        ch_section = ch_section_match.group(0) if ch_section_match else f'<h2>{xml_escape(ch_title)}</h2>{ch_body}'

        ch_xhtml = f'''<?xml version="1.0" encoding="UTF-8"?>
<html xmlns="http://www.w3.org/1999/xhtml">
<head><title>{xml_escape(ch_title)}</title>
<link rel="stylesheet" type="text/css" href="css/style.css"/></head>
<body>
{ch_section}
</body></html>'''
        zf.writestr(f'OEBPS/xhtml/{fn}', ch_xhtml)
        add_item(slug or f'ch{idx}', fn, 'application/xhtml+xml')
        nav_items.append(f'<li><a href="xhtml/{fn}">Chapter {idx+1}: {xml_escape(ch_title)}</a></li>')

    # Back cover
    back_match = _re.search(r'<div class="back-cover">(.*?)</div>', body_content, _re.DOTALL)
    if back_match:
        back_xhtml = f'''<?xml version="1.0" encoding="UTF-8"?>
<html xmlns="http://www.w3.org/1999/xhtml">
<head><title>About the Author</title>
<link rel="stylesheet" type="text/css" href="css/style.css"/></head>
<body><div class="back-cover">{back_match.group(1)}</div></body></html>'''
        zf.writestr('OEBPS/xhtml/back.xhtml', back_xhtml)
        add_item('back', 'back.xhtml', 'application/xhtml+xml')

    # Navigation
    nav = f'''<?xml version="1.0" encoding="UTF-8"?>
<html xmlns="http://www.w3.org/1999/xhtml" xmlns:epub="http://www.idpf.org/2007/ops">
<head><title>Table of Contents</title></head>
<body><nav epub:type="toc">
<h2>Contents</h2>
<ul>
<li><a href="xhtml/cover.xhtml">Cover</a></li>
<li><a href="xhtml/copyright.xhtml">Copyright</a></li>
<li><a href="xhtml/toc.xhtml">Table of Contents</a></li>
{"".join(nav_items)}
<li><a href="xhtml/back.xhtml">About the Author</a></li>
</ul>
</nav></body></html>'''
    zf.writestr('OEBPS/nav.xhtml', nav)
    manifest.append('<item id="nav" href="nav.xhtml" media-type="application/xhtml+xml" properties="nav"/>')

    # content.opf
    now = datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ")
    opf = f'''<?xml version="1.0" encoding="UTF-8"?>
<package xmlns="http://www.idpf.org/2007/opf" version="3.0" unique-identifier="book-id">
  <metadata>
    <dc:identifier id="book-id">{book_id}</dc:identifier>
    <dc:title>{xml_escape(title)}</dc:title>
    <dc:creator>{xml_escape(author)}</dc:creator>
    <dc:language>en</dc:language>
    <dc:date>{now}</dc:date>
    <meta property="dcterms:modified">{now}</meta>
  </metadata>
  <manifest>
    <item id="css" href="css/style.css" media-type="text/css"/>
    {"".join("    " + m + "\n" for m in manifest)}
  </manifest>
  <spine>
    {"".join("    " + s + "\n" for s in spine)}
  </spine>
</package>'''
    zf.writestr('OEBPS/content.opf', opf)
    zf.close()

    with open(output_path, 'wb') as f:
        f.write(buf.getvalue())
    return True

def generate_pdf(html_content, output_path):
    """Generate PDF using WeasyPrint."""
    HTML(string=html_content).write_pdf(output_path)
    return True

def main():
    for book_key, book_info in BOOKS.items():
        book_dir = book_info["dir"]
        publish_dir = os.path.join(BASE, book_dir, "publish")
        os.makedirs(publish_dir, exist_ok=True)

        print(f"\n{'='*60}")
        print(f"  {book_info['title']}")
        print(f"{'='*60}")

        # Load manuscript
        chapters = load_manuscript(book_dir)
        print(f"  Loaded {len(chapters)} chapters")

        # Generate HTML
        html = build_html(book_key, book_info, chapters)
        html_path = os.path.join(publish_dir, f"{book_key}.html")
        with open(html_path, "w", encoding="utf-8") as f:
            f.write(html)
        html_size = os.path.getsize(html_path)
        print(f"  ✅ HTML: {html_path} ({html_size/1024:.0f} KB)")

        # Generate EPUB
        epub_path = os.path.join(publish_dir, f"{book_key}.epub")
        create_epub(html, epub_path, book_info["title"], book_info["author"])
        epub_size = os.path.getsize(epub_path)
        print(f"  ✅ EPUB: {epub_path} ({epub_size/1024:.0f} KB)")

        # Generate PDF
        pdf_path = os.path.join(publish_dir, f"{book_key}.pdf")
        generate_pdf(html, pdf_path)
        pdf_size = os.path.getsize(pdf_path)
        print(f"  ✅ PDF: {pdf_path} ({pdf_size/1024:.0f} KB)")

        print(f"  ───────────────────────")
        print(f"  Total: {html_size/1024:.0f} + {epub_size/1024:.0f} + {pdf_size/1024:.0f} KB")

if __name__ == "__main__":
    main()
"}

