def load_chapters(book_dir):
    path = os.path.join(BASE, book_dir, "manuscript.md")
    with open(path, "r", encoding="utf-8") as f:
        c = f.read()
    lines = c.split("\n")
    chs, cur_t, cur_l, front = [], None, [], True
    for line in lines:
        s = line.strip()
        m = re.match(r'^## (?:Chapter|CHAPTER)\s+\d+\s*[—\-–]\s+.+', s)
        if m:
            front = False
            if cur_t is not None:
                chs.append((cur_t, "\n".join(cur_l).strip()))
            cur_t = s.lstrip("# ").strip()
            cur_l = []
        elif front:
            cur_l.append(line)
        else:
            cur_l.append(line)
    if cur_t and not front:
        chs.append((cur_t, "\n".join(cur_l).strip()))
    return chs

def md_html(text):
    lines = text.split("\n")
    h, il = [], False
    for ln in lines:
        s = ln.strip()
        if re.match(r'^## (?:Chapter|CHAPTER)', s): continue
        if s == "---":
            if il: h.append("</ul>"); il = False
            h.append("<hr />"); continue
        if not s:
            if il: h.append("</ul>"); il = False
            h.append(""); continue
        if s.startswith("- ") or s.startswith("* "):
            if not il: h.append("<ul>"); il = True
            h.append(f"<li>{xml_escape(s[2:])}</li>"); continue
        if il: h.append("</ul>"); il = False
        if s.startswith("*Mission AI:") or s.startswith("*Mission AI "):
            h.append(f'<p class="mission-ai">{xml_escape(s)}</p>'); continue
        if s.startswith("*") and s.endswith("*") and len(s) > 3:
            h.append(f'<p class="transition-note">{xml_escape(s.strip("*"))}</p>'); continue
        h.append(f"<p>{xml_escape(s)}</p>")
    if il: h.append("</ul>")
    return "\n".join(h)

def build(book, chs):
    t = book["title"]; s = book["subtitle"]; a = book["author"]; r = book["series"]

    cover_b64 = ""
    if os.path.exists(book["cover"]):
        with open(book["cover"], "rb") as f:
            cover_b64 = _b64.b64encode(f.read()).decode()

    css = textwrap.dedent(f"""\
