        .cover-page .author {{ font-size:12pt; color:#777; margin-top:2cm; }}
        .copyright-page {{ page-break-after:always; text-align:center; font-size:9pt; color:#666; padding-top:3cm; }}
        .copyright-page p {{ text-indent:0; margin:0.5em 0; }}
        .toc-page {{ page-break-after:always; }}
        .toc-page h2 {{ page-break-before:avoid; margin-top:0; padding-top:2cm; }}
        .toc-entry {{ text-indent:0; margin:0.2em 0; font-size:10pt; }}
        .back-cover {{ page-break-before:always; text-align:center; padding-top:3cm; }}
