        .mission-ai {{ font-style:italic; font-size:9.5pt; color:#666; text-indent:0; margin:0.5em 0; }}
        .character-quote {{ font-style:italic; font-size:10pt; color:#444; text-indent:0; margin:0.3em 0 1em 0; }}
    """)

    pts = []
