    pts.append(f'<div class="cover-page">{ci}<h1>{xml_escape(t)}</h1><p class="subtitle">{xml_escape(s)}</p><p class="author">{xml_escape(a)}</p><p class="series">{xml_escape(r)}</p></div>')
    pts.append(f'<div class="copyright-page"><h2>Copyright</h2><p>{xml_escape(t)}</p><p>Copyright \u00a9 2026 {xml_escape(a)}. All rights reserved.</p><p>This is a work of fiction.</p><p>First Edition: 2026</p></div>')

    toc = ['<div class="toc-page"><h2>Table of Contents</h2>']
    for i, (ct, _) in enumerate(chs):
        cl = re.sub(r'^(?:Chapter\s+\d+\s*[—\-–]\s*)', '', ct)
        toc.append(f'<p class="toc-entry">Chapter {i+1} &mdash; {xml_escape(cl.strip())}</p>')
