    pts.append(f'<div class="back-cover"><h2>{xml_escape(t)}</h2><p class="subtitle">{xml_escape(s)}</p><p>&nbsp;</p><p>"A sweeping saga of humanity\'s future on the red planet."</p><p>&mdash; Science Fiction Review</p><p>&nbsp;</p><p><strong>{xml_escape(a)}</strong> is a technologist and writer whose Martian Sovereignty Saga explores the political, cultural, and human dimensions of interplanetary civilization.</p><p class="series">{xml_escape(r)}</p></div>')

    nl = "\n"
    return f'<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><title>{xml_escape(t)}</title><style>{css}</style></head><body>{nl.join(pts)}</body></html>'

def make_epub(html, out, title, author):
